() => {
  // Find any canvas-ui mounted elements by counting canvases inside the DOM
  const canvases = document.querySelectorAll('canvas');
  const result = {
    canvasCount: canvases.length,
    layouts: Array.from(canvases).slice(0, 6).map(c => ({
      layoutsubtree: c.getAttribute('layoutsubtree'),
      hasLayoutSubtree: 'layoutsubtree' in c,
      parentClass: c.parentElement?.className?.slice(0, 60),
      visible: c.style.display !== 'none',
      width: c.width,
      height: c.height,
    })),
    webglSupported: (() => {
      try {
        const c = document.createElement('canvas');
        return !!(c.getContext('webgl2') || c.getContext('webgl'));
      } catch (e) { return 'threw: ' + e.message; }
    })(),
    htmlInCanvasFlag: (() => {
      try {
        const c = document.createElement('canvas');
        return 'drawElement' in c.getContext('webgl2' ?? c.getContext('webgl')) ?? false;
      } catch (e) { return 'unknown'; }
    })(),
  };
  return JSON.stringify(result, null, 2);
}

() => {
  // Get all canvas elements regardless of where they are mounted
  const all = document.querySelectorAll('canvas');
  // Check the [data-fx] attribute I added for debugging
  const fxDivs = document.querySelectorAll('[data-fx]');
  // Check for any canvas elements created with layoutsubtree
  const result = {
    canvasCount: all.length,
    fxDivs: fxDivs.length,
    fxDivsAttributes: Array.from(fxDivs).map(d => d.getAttribute('data-fx')).slice(0, 10),
    canvasDetails: Array.from(all).map(c => ({
      layoutsubtree: c.getAttribute('layoutsubtree'),
      id: c.id,
      parentClass: c.parentElement?.className?.slice(0, 60),
      role: c.getAttribute('role'),
      ariaHidden: c.getAttribute('aria-hidden'),
      width: c.width,
      height: c.height,
    })),
    // Also check if BackgroundFX is in DOM at all
    bgFxInReact: !!document.body.innerHTML.match(/data-fx|canvas-ui/i),
  };
  return JSON.stringify(result, null, 2);
}

() => {
  // Wallpaper uses this class - look for it
  const all = document.body.children;
  const root = document.getElementById('root');
  // Recursive walk
  const collectIds = (el, depth = 0, max = 5) => {
    if (!el || depth > max) return [];
    const out = [el.tagName + (el.className ? '.' + (typeof el.className === 'string' ? el.className.slice(0, 40).replace(/\s+/g, '.') : '') : '')];
    for (const child of el.children) {
      out.push(...collectIds(child, depth + 1, max));
    }
    return out;
  };
  const treeStructure = root ? Array.from(root.children).map(c => c.tagName + (c.className ? '.' + c.className.slice(0, 50).replace(/\s+/g, '.') : '')).slice(0, 30) : [];
  // Check fixed.inset-0 wallpaper class
  const fixedDivs = document.querySelectorAll('.fixed');
  const result = {
    bodyChildren: Array.from(all).map(c => c.tagName + '#' + (c.id || '?') + '.' + ((typeof c.className === 'string' ? c.className : '').slice(0, 60)).slice(0, 80),
    rootChildren: treeStructure,
    fixedDivs: Array.from(fixedDivs).map(d => ({
      classes: d.className.slice(0, 100),
      hasCanvasChild: !!d.querySelector('canvas'),
    })),
    // Wallpaper renders inside ViewportGuard which has its own wrapper
    viewportGuard: document.querySelector('[class*="ViewportGuard"], main, [role="main"]') ? 'found' : 'missing',
  };
  return JSON.stringify(result, null, 2);
}

() => {
  const result = {};
  // Walk root and collect all divs with their first 6 children types
  const root = document.getElementById('root');
  result.rootHTML = root ? root.innerHTML.slice(0, 800) : 'no root';
  result.bodyDirectChildren = Array.from(document.body.children).map(c => ({
    tag: c.tagName,
    id: c.id,
    class: typeof c.className === 'string' ? c.className.slice(0, 80) : '',
  }));
  // Find all div elements with fixed inset-0 (the wallpaper target class)
  const wallpaperCandidates = document.querySelectorAll('div.fixed');
  result.fixedCount = wallpaperCandidates.length;
  result.fixedClassList = Array.from(wallpaperCandidates).slice(0, 4).map(d => d.className.slice(0, 80));
  // Check internal siblings (ViewportGuard's children)
  result.viewportGuardChildren = (() => {
    const vg = document.querySelector('div.fixed')?.parentElement;
    return vg ? Array.from(vg.children).map(c => c.outerHTML.slice(0, 150)) : ['no vg'];
  })();
  return JSON.stringify(result, null, 2);
}

() => {
  const cssfx = document.querySelectorAll('[data-cssfx]');
  const canvases = document.querySelectorAll('canvas');
  const result = {
    cssfxCount: cssfx.length,
    canvasCount: canvases.length,
    cssfxList: Array.from(cssfx).slice(0, 8).map(el => ({
      effect: el.getAttribute('data-cssfx'),
      theme: el.getAttribute('data-cssfx-theme'),
      animationName: getComputedStyle(el).animationName,
      backgroundImage: getComputedStyle(el).backgroundImage.slice(0, 80),
      visible: el.offsetWidth > 0 && el.offsetHeight > 0,
      dimensions: `${el.offsetWidth}x${el.offsetHeight}`,
    })),
  };
  return JSON.stringify(result, null, 2);
}

async () => {
  // Find Sales button and click it via JS
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.getAttribute('aria-label')?.includes('Sales Sanctum'));
  if (!btn) return { error: 'no Sales button' };
  // Single-click to open
  btn.click();
  await new Promise(r => setTimeout(r, 1500));
  return { opened: true, count: document.querySelectorAll('canvas').length, cssfx: document.querySelectorAll('[data-cssfx]').length };
}

() => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const cssfx = document.querySelectorAll('[data-cssfx]');
      const samples = Array.from(cssfx).map(el => ({
        effect: el.getAttribute('data-cssfx'),
        theme: el.getAttribute('data-cssfx-theme'),
        accent: el.getAttribute('data-cssfx-accent'),
        bgColor: getComputedStyle(el).backgroundColor,
        dimensions: `${el.offsetWidth}x${el.offsetHeight}`,
      }));
      resolve({ count: cssfx.length, samples, rootHTML: document.getElementById('root')?.innerHTML?.length || 0 });
    }, 4000);
  });
}

() => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const result = {
        totalButtons: document.querySelectorAll('button').length,
        rootHTML: document.getElementById('root')?.innerHTML?.slice(0, 200) || '',
        bodyText: document.body.innerText?.slice(0, 200) || '',
        cssfx: document.querySelectorAll('[data-cssfx]').length,
      };
      resolve(result);
    }, 8000);
  });
}

() => {
  // Find any sales-related button and try a click
  const all = Array.from(document.querySelectorAll('button'));
  const labels = all.map(b => b.getAttribute('aria-label') || b.textContent?.slice(0, 30)).filter(Boolean);
  return { total: all.length, sample: labels.slice(0, 15) };
}
